<script lang="ts">
 import {onMount} from 'svelte';import {saveCard,cards,photos,syncPhotos,removePhoto,type ObjectCard,type PhotoDraft} from '$lib/offline';import {invalidateAll} from '$app/navigation';
 let {model,t,tenantId}:{model:Record<string,Record<string,any>[]>;t:(s:string)=>string;tenantId:string}=$props();let kind=$state<ObjectCard['kind']>('lots'),selected=$state(''),saved=$state<ObjectCard[]>([]),files=$state<PhotoDraft[]>([]),message=$state('');
 onMount(()=>{const refresh=async()=>{saved=await cards(tenantId);files=await photos(tenantId);};refresh();window.addEventListener('vinea-drafts-changed',refresh);return()=>window.removeEventListener('vinea-drafts-changed',refresh);});
 async function download(){const record=model[kind].find(r=>r.id===selected);if(!record)return;const related:Record<string,Record<string,any>[]>={};for(const key of ['positions','analyses','tasks','notes','field_operations','maturity_samples','maintenance','cleanings'])related[key]=(model[key]??[]).filter(r=>kind==='lots'?r.lot_id===record.id:kind==='vineyards'?r.vineyard_id===record.id:r.vessel_id===record.id);await saveCard(tenantId,kind,record,related);message=t('cardSaved');}
 async function upload(){await syncPhotos(tenantId);await invalidateAll();}
</script>
<section class="card"><h2>{t('offlineCards')}</h2><p class="muted">{t('offlineCardHint')}</p><form onsubmit={(e)=>{e.preventDefault();download();}}><label>{t('objectType')}<select bind:value={kind} onchange={()=>selected=''}>{#each ['lots','vineyards','vessels'] as k}<option value={k}>{t(k)}</option>{/each}</select></label><label>{t('name')}<select required bind:value={selected}><option value="">—</option>{#each model[kind]??[] as r}<option value={r.id}>{r.code} · {r.name}</option>{/each}</select></label><button>{t('downloadCard')}</button></form><p role="status">{message}</p><ul>{#each saved as c}<li>{c.record.code} · {c.record.name} · {c.capturedAt}</li>{/each}</ul><a href="/offline">{t('openOffline')}</a>{#if files.length}<h3>{t('photosPending')} · {files.length}</h3><button onclick={upload}>{t('syncPhotos')}</button>{#each files as f}<p>{f.file.name} {f.error?t(f.error):''} <button onclick={()=>removePhoto(f.id)}>{t('deleteDraft')}</button></p>{/each}{/if}</section>
<style>form{display:grid;gap:14px;grid-template-columns:repeat(auto-fit,minmax(160px,1fr));margin:18px 0}ul{line-height:2}</style>
